	test(`custom forced retry preserves ${abort ? 'user abort' : 'timeout'}`, async t => {
		const controller = new AbortController();
		let calls = 0;
		await t.throwsAsync(ky('https://example.com', {
			signal: controller.signal,
			timeout: abort ? false : 20,
			async fetch(request) {
				if (++calls === 1) {
